  const growthServices = SERVICES.slice(4, 8);
  const opsServices = SERVICES.slice(8, 12);

  return (
    <nav className="fixed top-0 left-0 right-0 z-50 glass-morphism border-b border-white/10 px-6 py-4">
      <div className="max-w-7xl mx-auto flex justify-between items-center">
        {/* Logo - clicking this returns to home */}
        <button 
          onClick={() => handleLinkClick('', false)} 
          className="flex items-center gap-3 group transition-transform active:scale-95"
        >
          <div className="w-9 h-9 rounded-lg overflow-hidden border border-blue-500/30 flex-shrink-0 bg-blue-600/20">
            <img 
              src="https://lh3.googleusercontent.com/d/16MsRTezCaczZBh9aG6sz3HqZTDB62ve_" 
              alt="Ritehly Quimbo" 
              className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-300 scale-[1.1]"
            />
          </div>
          <span className="text-xl font-bold tracking-tight uppercase text-white">RITEHLY<span className="text-blue-500">QUIMBO</span></span>
        </button>

        {/* Desktop Navigation */}
        <div className="hidden lg:flex items-center gap-8 text-[11px] font-bold uppercase tracking-widest text-gray-400">

          {/* Services Mega Menu */}
          <div 
            className="relative group py-2"
            onMouseEnter={() => setIsServicesOpen(true)}
            onMouseLeave={() => setIsServicesOpen(false)}
          >
            <button className={`flex items-center gap-1 hover:text-white transition-colors ${isServicesOpen ? 'text-white' : ''}`}>
              Services
              <svg className={`w-3 h-3 transition-transform duration-300 ${isServicesOpen ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" />
              </svg>
            </button>

            {/* Mega Dropdown */}
            <div className={`absolute top-full -left-[300px] pt-4 transition-all duration-300 ${isServicesOpen ? 'opacity-100 translate-y-0 pointer-events-auto' : 'opacity-0 -translate-y-2 pointer-events-none'}`}>
              <div className="glass-morphism border border-white/10 rounded-[2.5rem] p-10 shadow-[0_50px_100px_-20px_rgba(0,0,0,0.8)] w-[900px] flex overflow-hidden relative">

                {/* Background Accent Photo (Subtle) */}
                <div className="absolute right-0 bottom-0 top-0 w-1/3 pointer-events-none">
                   <img 
                    src="https://lh3.googleusercontent.com/d/16MsRTezCaczZBh9aG6sz3HqZTDB62ve_" 
                    alt="Background Profile"
                    className="h-full w-full object-cover object-top opacity-10 grayscale brightness-150 contrast-125"
                   />
                   <div className="absolute inset-0 bg-gradient-to-l from-transparent via-[#030712] to-[#030712]"></div>
                </div>

                <div className="relative z-10 grid grid-cols-3 gap-12 w-full">
                  {/* Search Strategy */}
                  <div className="space-y-6">
                    <h4 className="text-[10px] text-blue-500 font-black tracking-[0.3em] uppercase mb-4 border-b border-white/5 pb-2">Search Strategy</h4>
                    <div className="space-y-2">
                      {searchServices.map((s) => (
                        <button key={s.id} onClick={() => handleLinkClick(s.id, true)} className="flex items-center gap-4 p-2 rounded-xl hover:bg-white/5 transition-all text-left w-full group/item">
                          <span className="text-xl group-hover/item:scale-110 transition-transform">{s.icon}</span>
                          <div>
                            <div className="text-white text-[10px] font-black group-hover/item:text-blue-400">{s.title}</div>
                            <div className="text-gray-500 text-[9px] font-medium truncate w-32">{s.description}</div>
                          </div>
                        </button>
                      ))}
                    </div>
                  </div>

                  {/* Growth & Ads */}
                  <div className="space-y-6">
                    <h4 className="text-[10px] text-purple-500 font-black tracking-[0.3em] uppercase mb-4 border-b border-white/5 pb-2">Market Domination</h4>
                    <div className="space-y-2">
                      {growthServices.map((s) => (
                        <button key={s.id} onClick={() => handleLinkClick(s.id, true)} className="flex items-center gap-4 p-2 rounded-xl hover:bg-white/5 transition-all text-left w-full group/item">
                          <span className="text-xl group-hover/item:scale-110 transition-transform">{s.icon}</span>
                          <div>
                            <div className="text-white text-[10px] font-black group-hover/item:text-purple-400">{s.title}</div>
