                  Book Specialist Correction
                </button>
                <a 
                  href="tel:09611525318"
                  className="px-10 py-4 bg-white/5 border border-white/20 text-white font-bold rounded-xl hover:bg-white/10 transition-all uppercase tracking-tighter flex items-center justify-center gap-3"
